//! Specialized fast-path normal-form backend for type-$A$ Iwahori–Hecke algebras $H_n(q)$
//! using Coxeter permutation multiplication and Bokut–Shiao `DegLex`-minimal reduced words.
//!
//! ## Presentation and Completion
//!
//! On `num_strands = n` strands ($n \ge 1$), $H_n$ is generated by $\sigma_0, \dots, \sigma_{n-2}$
//! subject to:
//! - Quadratic relation: $\sigma_i^2 = h\,\sigma_i + q_0\,\mathbf{1}$ (balanced default: $q_0 = 1$,
//!   $h = q - q^{-1}$; Iwahori normalisation: $h = q - 1$, $q_0 = q$).
//! - Far commutation: $\sigma_i \sigma_j = \sigma_j \sigma_i$ for $|i - j| \ge 2$.
//! - Braid (Yang–Baxter) relation: $\sigma_{i+1}\sigma_i\sigma_{i+1} = \sigma_i\sigma_{i+1}\sigma_i$.
//!
//! Under [`DegLex`](crate::order::DegLex) with $\sigma_0 < \sigma_1 < \dots < \sigma_{n-2}$, the
//! uncompleted rule set fails confluence for $n \ge 5$ (`4` generators $\sigma_0,\sigma_1,\sigma_2,\sigma_3$):
//! overlapping $\sigma_3\sigma_2\sigma_3 \to \sigma_2\sigma_3\sigma_2$ with
//! $\sigma_3\sigma_1 \to \sigma_1\sigma_3$ on $\sigma_3\sigma_2\sigma_3\sigma_1$ yields the
//! irreducible S-polynomial $\sigma_2\sigma_3\sigma_2\sigma_1 - \sigma_3\sigma_2\sigma_1\sigma_3 \ne 0$.
//!
//! Adjoining the Bokut–Shiao (2001) / Kang–Lee–Lee–Oh (2002) rule family
//! $$\sigma_i \sigma_{i-1} \cdots \sigma_j \sigma_i \longrightarrow \sigma_{i-1} \sigma_i \sigma_{i-1} \cdots \sigma_j \quad (0 \le j < i)$$
//! yields a finite Gröbner–Shirshov basis of normal-form dimension $n!$, where each permutation
//! $w \in S_n$ is represented by its unique lexicographically smallest reduced Coxeter word.

use std::collections::BTreeMap;

use crate::free_alg::{FreeAlg, Word};
use crate::scalar::RingScalar;
use crate::shirshov::{NormalFormBasis, RewriteRule};

/// Combinatorial normal-form engine for the type-$A$ Iwahori–Hecke algebra $H_n$ on `num_strands` strands.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BokutShiaoHecke<R> {
    num_strands: usize,
    linear_coeff_h: R,
    const_coeff_q0: R,
}

impl<R: RingScalar> BokutShiaoHecke<R> {
    /// Balanced Iwahori–Hecke algebra $H_n(q)$ on `num_strands` strands ($\sigma_0, \dots, \sigma_{n-2}$)
    /// with quadratic relation $\sigma_i^2 = h\,\sigma_i + \mathbf{1}$.
    pub fn new(num_strands: usize, h: R) -> Self {
        assert!(num_strands >= 1, "num_strands must be >= 1");
        Self {
            num_strands,
            linear_coeff_h: h,
            const_coeff_q0: R::one(),
        }
    }

    /// Construct from explicit generator count `m` (`num_strands = m + 1`, generators `0..m`).
    pub fn from_num_generators(num_generators: usize, h: R) -> Self {
        Self::new(num_generators + 1, h)
    }

    /// General two-parameter quadratic relation $\sigma_i^2 = h\,\sigma_i + q_0\,\mathbf{1}$.
    pub fn with_quadratic(num_strands: usize, linear_coeff_h: R, const_coeff_q0: R) -> Self {
        assert!(num_strands >= 1, "num_strands must be >= 1");
        Self {
            num_strands,
            linear_coeff_h,
            const_coeff_q0,
        }
    }

    /// Number of strands $n$ (normal-form basis has dimension $n!$).
    pub fn num_strands(&self) -> usize {
        self.num_strands
    }

    /// Number of Artin/Hecke generators $\max(0, n - 1)$.
    pub fn num_generators(&self) -> usize {
        self.num_strands.saturating_sub(1)
    }

    /// Linear quadratic parameter $h$ in $\sigma_i^2 = h\,\sigma_i + q_0\,\mathbf{1}$.
    pub fn h(&self) -> &R {
        &self.linear_coeff_h
    }

    /// Constant quadratic parameter $q_0$ in $\sigma_i^2 = h\,\sigma_i + q_0\,\mathbf{1}$.
    pub fn q0(&self) -> &R {
        &self.const_coeff_q0
    }

    /// Inverse generator $\sigma_i^{-1} = q_0^{-1}(\sigma_i - h\,\mathbf{1})$ when $q_0$ is a unit.
    pub fn generator_inverse(&self, i: usize) -> Option<FreeAlg<usize, R>> {
        assert!(
            i < self.num_generators(),
            "generator index {i} out of range for {} strands",
            self.num_strands
        );
        let q0_inv = self.const_coeff_q0.try_inv()?;
        let diff =
            &FreeAlg::generator(i) - &FreeAlg::scalar(self.linear_coeff_h.clone());
        Some(diff.scale(&q0_inv))
    }

    /// Standard uncompleted rule set `{quadratic, far-commutation, Yang-Baxter}` on `num_strands` strands.
    pub fn uncompleted_rules_with(
        num_strands: usize,
        h: &R,
        q0: &R,
    ) -> Vec<RewriteRule<usize, R>> {
        let m = num_strands.saturating_sub(1);
        let mut rules = Vec::new();
        // 1. Quadratic: sigma_i * sigma_i -> h * sigma_i + q0
        for i in 0..m {
            let rhs = &FreeAlg::term(vec![i], h.clone()) + &FreeAlg::scalar(q0.clone());
            rules.push(RewriteRule {
                lhs: vec![i, i],
                rhs,
            });
        }
        // 2. Far commutation: sigma_i * sigma_j -> sigma_j * sigma_i for i > j + 1
        for i in 0..m {
            for j in 0..i {
                if i > j + 1 {
                    rules.push(RewriteRule {
                        lhs: vec![i, j],
                        rhs: FreeAlg::word(vec![j, i]),
                    });
                }
            }
        }
        // 3. Yang-Baxter braid relation: sigma_{i+1} * sigma_i * sigma_{i+1} -> sigma_i * sigma_{i+1} * sigma_i
        for i in 0..m.saturating_sub(1) {
            rules.push(RewriteRule {
                lhs: vec![i + 1, i, i + 1],
                rhs: FreeAlg::word(vec![i, i + 1, i]),
            });
        }
        rules
    }

    /// Balanced ($q_0 = 1$) uncompleted Hecke rules `{quadratic, far-commutation, Yang-Baxter}`.
    pub fn uncompleted_rules(num_strands: usize, h: &R) -> Vec<RewriteRule<usize, R>> {
        Self::uncompleted_rules_with(num_strands, h, &R::one())
    }

    /// Completed Bokut–Shiao Gröbner–Shirshov rule set on `num_strands` strands:
    /// `{quadratic, far-commutation}` plus $\sigma_i\sigma_{i-1}\cdots\sigma_j\sigma_i \to \sigma_{i-1}\sigma_i\sigma_{i-1}\cdots\sigma_j$
    /// for all $0 \le j < i < n - 1$ (subsuming Yang–Baxter at $j = i - 1$).
    pub fn completed_rules_with(
        num_strands: usize,
        h: &R,
        q0: &R,
    ) -> Vec<RewriteRule<usize, R>> {
        let m = num_strands.saturating_sub(1);
        let mut rules = Vec::new();
        for i in 0..m {
            let rhs = &FreeAlg::term(vec![i], h.clone()) + &FreeAlg::scalar(q0.clone());
            rules.push(RewriteRule {
                lhs: vec![i, i],
                rhs,
            });
        }
        for i in 0..m {
            for j in 0..i {
                if i > j + 1 {
                    rules.push(RewriteRule {
                        lhs: vec![i, j],
                        rhs: FreeAlg::word(vec![j, i]),
                    });
                }
            }
        }
        // Bokut-Shiao family for 0 <= j < i < m:
        for i in 1..m {
            for j in 0..i {
                let mut lhs = Vec::with_capacity(i - j + 2);
                for k in (j..=i).rev() {
                    lhs.push(k);
                }
                lhs.push(i);

                let mut rhs_word = Vec::with_capacity(i - j + 2);
                rhs_word.push(i - 1);
                rhs_word.push(i);
                for k in (j..i).rev() {
                    rhs_word.push(k);
                }
                rules.push(RewriteRule {
                    lhs,
                    rhs: FreeAlg::word(rhs_word),
                });
            }
        }
        rules
    }

    /// Balanced ($q_0 = 1$) completed Bokut–Shiao Gröbner–Shirshov rules.
    pub fn completed_rules(num_strands: usize, h: &R) -> Vec<RewriteRule<usize, R>> {
        Self::completed_rules_with(num_strands, h, &R::one())
    }

    /// Compute the unique `DegLex`-minimal Coxeter reduced word (Bokut–Shiao normal form)
    /// of a permutation `perm` of `0..n`.
    pub fn lex_first_reduced_word(perm: &[u16]) -> Word<usize> {
        let n = perm.len();
        let mut cur = perm.to_vec();
        let mut inv = vec![0usize; n];
        for (pos, &val) in cur.iter().enumerate() {
            inv[val as usize] = pos;
        }
        let mut out = Vec::new();
        loop {
            // Left descent condition: s_i (swapping values i and i+1) reduces length iff inv[i+1] < inv[i].
            let mut found = None;
            for i in 0..n.saturating_sub(1) {
                if inv[i + 1] < inv[i] {
                    found = Some(i);
                    break;
                }
            }
            match found {
                None => break,
                Some(i) => {
                    out.push(i);
                    let pos_i = inv[i];
                    let pos_ip1 = inv[i + 1];
                    cur.swap(pos_i, pos_ip1);
                    inv[i] = pos_ip1;
                    inv[i + 1] = pos_i;
                }
            }
        }
        out
    }

    /// Right-multiply a sparse permutation-basis combination $\sum_p c_p T_p$ by $\sigma_i$.
    fn right_mul_gen(&self, state: BTreeMap<Vec<u16>, R>, gen: usize) -> BTreeMap<Vec<u16>, R> {
        assert!(
            gen < self.num_generators(),
            "Hecke generator {gen} out of range for {} strands (max generator {})",
            self.num_strands,
            self.num_generators().saturating_sub(1)
        );
        let mut out: BTreeMap<Vec<u16>, R> = BTreeMap::new();
        for (perm, coeff) in state {
            if coeff.is_zero() {
                continue;
            }
            let mut swapped = perm.clone();
            swapped.swap(gen, gen + 1);
            if perm[gen] < perm[gen + 1] {
                // Length increases: T_p * sigma_i = T_{p s_i}
                Self::accum_perm(&mut out, swapped, coeff);
            } else {
                // Length decreases: T_p * sigma_i = h * T_p + q0 * T_{p s_i}
                let h_term = coeff.mul_val(&self.linear_coeff_h);
                let q_term = coeff.mul_val(&self.const_coeff_q0);
                Self::accum_perm(&mut out, perm, h_term);
                Self::accum_perm(&mut out, swapped, q_term);
            }
        }
        out
    }

    fn accum_perm(map: &mut BTreeMap<Vec<u16>, R>, perm: Vec<u16>, delta: R) {
        if delta.is_zero() {
            return;
        }
        if let Some(existing) = map.get_mut(&perm) {
            let sum = existing.add_val(&delta);
            if sum.is_zero() {
                map.remove(&perm);
            } else {
                *existing = sum;
            }
        } else {
            map.insert(perm, delta);
        }
    }

    /// Expand a word directly in the Coxeter permutation basis $\{T_p : p \in S_n\}$.
    pub fn word_to_perm_basis(&self, word: &[usize]) -> BTreeMap<Vec<u16>, R> {
        let id: Vec<u16> = (0..self.num_strands as u16).collect();
        let mut state = BTreeMap::new();
        state.insert(id, R::one());
        for &g in word {
            state = self.right_mul_gen(state, g);
        }
        state
    }

    /// Enumerate all $n!$ Bokut–Shiao normal-form basis words for $H_n$ (for small $n$).
    pub fn all_normal_form_words(&self) -> Vec<Word<usize>> {
        let mut perms = Vec::new();
        let mut cur: Vec<u16> = (0..self.num_strands as u16).collect();
        fn permute(idx: usize, cur: &mut Vec<u16>, out: &mut Vec<Word<usize>>) {
            if idx == cur.len() {
                out.push(BokutShiaoHecke::<i64>::lex_first_reduced_word(cur));
                return;
            }
            for j in idx..cur.len() {
                cur.swap(idx, j);
                permute(idx + 1, cur, out);
                cur.swap(idx, j);
            }
        }
        permute(0, &mut cur, &mut perms);
        perms.sort_by(|a, b| a.len().cmp(&b.len()).then_with(|| a.cmp(b)));
        perms
    }

    /// Evaluate the Ocneanu–Markov trace $\operatorname{tr}_M(x)$ normalized by
    /// $\operatorname{tr}_M(\mathbf{1}) = 1$ and $\operatorname{tr}_M(w \sigma_{k-1}) = z \cdot \operatorname{tr}_M(w)$
    /// for $w \in H_{k-1}$.
    pub fn ocneanu_trace(&self, elem: &FreeAlg<usize, R>, z: &R) -> R {
        let reduced = self.reduce(elem);
        let mut total = R::zero();
        for (w, c) in reduced.terms() {
            let wt = self.trace_reduced_word(w, z);
            total = total.add_val(&c.mul_val(&wt));
        }
        total
    }

    fn trace_reduced_word(&self, word: &[usize], z: &R) -> R {
        if word.is_empty() {
            return R::one();
        }
        let max_g = *word.iter().max().unwrap();
        let count_max = word.iter().filter(|&&g| g == max_g).count();
        if count_max == 1 {
            // Markov II: sigma_{max_g} appears once; conjugate/peel it by multiplying remaining letters
            let pos = word.iter().position(|&g| g == max_g).unwrap();
            let mut sub_word = Vec::with_capacity(word.len() - 1);
            sub_word.extend_from_slice(&word[pos + 1..]);
            sub_word.extend_from_slice(&word[..pos]);
            let reduced_sub = self.reduce_word(&sub_word);
            let mut acc = R::zero();
            for (sw, sc) in reduced_sub.terms() {
                acc = acc.add_val(&sc.mul_val(&self.trace_reduced_word(sw, z)));
            }
            z.mul_val(&acc)
        } else {
            // In a reduced Coxeter word of S_n, can the maximum generator m appear >= 2 times?
            // No! Every reduced word in S_{m+2} uses its highest generator s_m at most ONCE!
            unreachable!("a Coxeter reduced word in S_n uses its maximum generator at most once")
        }
    }
}

impl<R: RingScalar> NormalFormBasis<R, usize> for BokutShiaoHecke<R> {
    fn reduce_word(&self, word: &[usize]) -> FreeAlg<usize, R> {
        let perm_map = self.word_to_perm_basis(word);
        let mut terms = BTreeMap::new();
        for (perm, coeff) in perm_map {
            if !coeff.is_zero() {
                terms.insert(Self::lex_first_reduced_word(&perm), coeff);
            }
        }
        FreeAlg::from_terms(terms)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::order::DegLex;
    use crate::scalar::LaurentPoly;
    use crate::shirshov::{CompletionConfig, ShirshovEngine};

    #[test]
    fn hecke_gs_n4_counterexample_fails_before_completion_and_resolves_after() {
        // Matches UGB/GrobnerShirshov/HeckeGS.lean `hecke_not_gs_basis_four` & `HeckeCompletion.lean`:
        // 4 generators sigma_0..sigma_3 (H_5(q)):
        // S-polynomial of (sigma_3 sigma_2 sigma_3 - sigma_2 sigma_3 sigma_2) and
        // (sigma_3 sigma_1 - sigma_1 sigma_3) on ambient word sigma_3 sigma_2 sigma_3 sigma_1 is
        // w1 - w2 = sigma_2 sigma_3 sigma_2 sigma_1 - sigma_3 sigma_2 sigma_1 sigma_3.
        type L = LaurentPoly<i64>;
        let h = L::h();

        let uncompleted =
            ShirshovEngine::from_rules(BokutShiaoHecke::<L>::uncompleted_rules(5, &h), DegLex)
                .unwrap();
        assert!(!uncompleted.is_confluent());

        let w1 = FreeAlg::<usize, L>::word(vec![2, 3, 2, 1]);
        let w2 = FreeAlg::<usize, L>::word(vec![3, 2, 1, 3]);
        let spoly = &w1 - &w2;

        // 1. Both w1 and w2 are irreducible under the uncompleted presentation, so spoly != 0:
        assert_eq!(uncompleted.reduce(&w1), w1);
        assert_eq!(uncompleted.reduce(&w2), w2);
        assert_eq!(uncompleted.reduce(&spoly), spoly);
        assert!(!uncompleted.reduce(&spoly).is_zero());

        // 2. Explicit Bokut-Shiao completion is confluent and reduces spoly -> 0:
        let completed =
            ShirshovEngine::from_rules(BokutShiaoHecke::<L>::completed_rules(5, &h), DegLex)
                .unwrap();
        assert!(completed.is_confluent());
        assert_eq!(completed.reduce(&w2), w1);
        assert!(completed.reduce(&spoly).is_zero());

        // 3. Dynamic 1B Buchberger-Shirshov completion discovers Bokut-Shiao automatically:
        let mut dynamic = uncompleted;
        let cert = dynamic.complete(&CompletionConfig::default()).unwrap();
        assert!(cert.is_complete);
        assert!(dynamic.reduce(&spoly).is_zero());

        // 4. Fast-path 1A BokutShiaoHecke agrees identically with completed GS engine:
        let fast = BokutShiaoHecke::new(5, h);
        assert_eq!(fast.all_normal_form_words().len(), 120); // 5! = 120
        assert_eq!(fast.reduce(&w2), w1);
        assert!(fast.reduce(&spoly).is_zero());

        // Cross-check random-looking degree-6 words between fast Coxeter reducer and dynamic GS engine:
        for sample in [
            vec![3, 2, 1, 0, 3, 2],
            vec![2, 1, 2, 0, 1, 2],
            vec![3, 3, 2, 3, 1, 3],
            vec![1, 0, 3, 2, 1, 0],
        ] {
            assert_eq!(
                fast.reduce_word(&sample),
                dynamic.reduce_word(&sample),
                "mismatch on word {sample:?}"
            );
        }
    }
}
